urlset:
{% if config.extra.docs_version != "dev" and "-" not in config.extra.docs_version %}
  {% for file in pages %}
    {% if not file.page.is_link and file.src_uri != "index.md" and file.page.canonical_url %}

    {{ file.page.canonical_url | e }}
    {% if file.page.update_date %}{{ file.page.update_date }}{% endif %}

    {% endif %}
  {% endfor %}
{% endif %}
